int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(struct rds_atomic_args)))
        return ret;

    struct rds_atomic_args *args = CMSG_DATA(cmsg);
    struct rds_atomic_op *op = &rm->atomic_op;

    if (op->active)
        return -EBUSY;

    switch (args->op_type) {
    case RDS_ATOMIC_ADD:
        op->type = RDS_ATOMIC_ADD;
        op->param.add.value = args->u.add.value;
        break;
    case RDS_ATOMIC_FETCH_AND_ADD:
        op->type = RDS_ATOMIC_FETCH_AND_ADD;
        op->param.fetch_add.delta = args->u.fetch_add.delta;
        break;
    case RDS_ATOMIC_COMPARE_AND_SWAP:
        op->type = RDS_ATOMIC_COMPARE_AND_SWAP;
        op->param.cmp_swap.old_val = args->u.cmp_swap.old_val;
        op->param.cmp_swap.new_val = args->u.cmp_swap.new_val;
        break;
    default:
        return ret;
    }

    op->sg = kmalloc(args->sg_len * sizeof(struct scatterlist), GFP_KERNEL);
    if (!op->sg)
        return -ENOMEM;

    memcpy(op->sg, args->sg_list, args->sg_len * sizeof(struct scatterlist));
    op->sg_count = args->sg_len;

    if (args->align) {
        if (!IS_ALIGNED(args->offset, args->align)) {
            kfree(op->sg);
            return -EINVAL;
        }
        op->offset = args->offset;
    } else {
        op->offset = 0;
    }

    if (args->notify) {
        op->notify = kmalloc(sizeof(struct rds_notifier), GFP_KERNEL);
        if (!op->notify) {
            kfree(op->sg);
            return -ENOMEM;
        }
        op->notify->type = args->notify_type;
        op->notify->cb = args->notify_cb;
    }

    op->remote_addr = args->remote_addr;
    op->key = args->key;
    op->active = 1;

    return 0;
}

int rds_atomic_op(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg) {
    struct rds_atomic_args args;
    int ret = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(args)))
        return ret;

    if (rs->atomic_op_active)
        return -EBUSY;

    memcpy(&args, CMSG_DATA(cmsg), sizeof(args));

    switch (args.op_type) {
        case RDS_ATOMIC_ADD:
            rm->op_type = RDS_OP_ADD;
            break;
        case RDS_ATOMIC_CMPXCHG:
            rm->op_type = RDS_OP_CMPXCHG;
            break;
        default:
            return ret;
    }

    rm->sg = kmalloc(args.sg_len, GFP_KERNEL);
    if (!rm->sg)
        return -ENOMEM;

    if (args.address_unaligned) {
        rm->local_addr = kmap_atomic(args.address);
    } else {
        rm->local_addr = args.address;
    }

    if (args.notify) {
        rm->notifier = kzalloc(sizeof(struct rds_notifier), GFP_KERNEL);
        if (!rm->notifier) {
            kfree(rm->sg);
            return -ENOMEM;
        }
    }

    rm->remote_addr = args.remote_address;
    rm->key = args.key;

    rs->atomic_op_active = 1;

    return 0;
}

int rds_atomic_message_op(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int err = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(0))
        return err;

    if (rm->atomic_op_active)
        return -EBUSY;

    struct atomic_op_args *args = (struct atomic_op_args *)CMSG_DATA(cmsg);
    if (!args)
        return err;

    rm->atomic_op_type = args->op_type;
    rm->atomic_op_size = args->size;

    struct scatterlist *sg = kmalloc(sizeof(*sg) * args->num_segments, GFP_KERNEL);
    if (!sg)
        return -ENOMEM;

    rm->atomic_op_sg = sg;
    rm->atomic_op_nents = args->num_segments;

    for (int i = 0; i < args->num_segments; i++) {
        sg_set_page(&sg[i], args->segments[i].page, args->segments[i].size, args->segments[i].offset);
    }

    if (!is_aligned(args->remote_addr, 8)) {
        return -EINVAL;
    }

    rm->atomic_op_addr = args->remote_addr;
    rm->atomic_op_key = args->key;

    if (args->notify) {
        struct rds_notifier *notifier = kmalloc(sizeof(*notifier), GFP_KERNEL);
        if (!notifier) {
            kfree(sg);
            return -ENOMEM;
        }

        rm->atomic_notifier = notifier;
        notifier->cb = args->notify_cb;
        notifier->data = args->notify_data;
    }

    rm->atomic_op_active = 1;
    return 0;
}

int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg) {
    int ret = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(int))) {
        goto out;
    }

    if (rs->atomic_op_active) {
        ret = -EBUSY;
        goto out;
    }

    int op_type = *(int *)CMSG_DATA(cmsg);
    struct rds_atomic_args *args = kmalloc(sizeof(*args), GFP_KERNEL);
    if (!args) {
        ret = -ENOMEM;
        goto out;
    }

    args->sg = kmalloc(sizeof(*args->sg) * args->num_entries, GFP_KERNEL);
    if (!args->sg) {
        ret = -ENOMEM;
        kfree(args);
        goto out;
    }

    if (args->addr % 4 != 0) {
        ret = -EINVAL;
        kfree(args->sg);
        kfree(args);
        goto out;
    }

    if (args->notify_required) {
        args->notifier = kmalloc(sizeof(*args->notifier), GFP_KERNEL);
        if (!args->notifier) {
            ret = -ENOMEM;
            kfree(args->sg);
            kfree(args);
            goto out;
        }
    }

    rm->atomic_op = op_type;
    args->remote_addr = rs->remote_addr;
    args->key = rs->key;
    rs->atomic_op_active = 1;

    ret = 0;

out:
    return ret;
}

int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = -EINVAL;
    struct rds_atomic_op_args *args;
    struct scatterlist *sg;
    struct rds_atomic_notifier *notifier;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(*args)))
        return ret;

    args = CMSG_DATA(cmsg);

    if (rs->atomic_in_progress)
        return -EBUSY;

    if (args->type >= RDS_ATOMIC_OP_TYPE_MAX)
        return ret;

    sg = kzalloc(sizeof(*sg) * args->sg_count, GFP_KERNEL);
    if (!sg)
        return -ENOMEM;

    if (args->flags & RDS_ATOMIC_OP_FLAG_NOTIFY) {
        notifier = kzalloc(sizeof(*notifier), GFP_KERNEL);
        if (!notifier) {
            kfree(sg);
            return -ENOMEM;
        }
        notifier->pid = args->notify_pid;
        rm->notifier = notifier;
    }

    rm->atomic_op = args->type;
    rm->atomic_addr = args->addr;
    rm->atomic_key = args->key;

    return 0;
}
